"""Recompute the preregistered nine-case capability summary from closed raw archives."""
from pathlib import Path
import argparse,csv,hashlib,json,re,sqlite3

p=argparse.ArgumentParser();p.add_argument('--closed',type=Path,required=True);p.add_argument('--final',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
cohorts=[('qwen-source025',[(a.closed,'qwen-source025',i)for i in range(3)]),
 ('next-source025',[(a.final,'next-source025-recovery335',0),(a.closed,'next-source025',1),(a.final,'next-source025-recovery335',2)]),
 ('next-mini',[(a.final,'next-mini',i)for i in range(3)])]
rows=[]
for cohort,locations in cohorts:
 for root,arm,i in locations:
  d=root/'capability'/arm/f'task{i+1:03d}';s=json.loads((d/'case-summary.json').read_text());result=json.loads((d/'result.json').read_text());u=s['usage'];o=s['official'];g=result['rows'][0]['grade'];assert o['official_protocol_valid']and o['test_outcomes_equal']and u['accounting_valid'];assert u['uncertain_or_pending_call_count']==0
  db=d/'run.sqlite3';before=hashlib.sha256(db.read_bytes()).hexdigest();c=sqlite3.connect(db.as_uri()+'?mode=ro&immutable=1',uri=True);first=json.loads(c.execute('SELECT payload FROM trace WHERE kind="model_request" ORDER BY seq LIMIT 1').fetchone()[0]);last=json.loads(c.execute('SELECT payload FROM trace WHERE kind="model_response" ORDER BY seq DESC LIMIT 1').fetchone()[0]);state,reason=c.execute('SELECT state,result FROM tasks').fetchone();c.close();assert hashlib.sha256(db.read_bytes()).hexdigest()==before
  encoded=json.dumps({k:first[k]for k in ['messages','tools']},ensure_ascii=False,sort_keys=True,separators=(',',':')).encode();stdout=g.get('execution',{}).get('stdout','');matched=re.search(r'Required tests that passed:\s*(\d+)',stdout);mini=d/'mini.traj.json';exit_status=json.loads(mini.read_text())['info']['exit_status']if mini.exists()else None
  row={'cohort':cohort,'original_arm':arm,'index':i,'task_id':s['task_id'],'success':o['success'],'official_protocol_valid':True,'independent_test_outcomes_equal':True,'actual_api_tokens':u['actual_api_tokens'],'input_tokens':u['input_tokens'],'output_tokens':u['output_tokens'],'actual_api_calls':len(u['calls']),'accepted_reservation_tokens_sum':u['accepted_reservation_tokens_sum'],'reservation_denied_count':u['reservation_denied_count'],'outstanding_reserved_tokens':u['outstanding_reserved_tokens'],'uncertain_or_pending_call_count':u['uncertain_or_pending_call_count'],'context_window':262144,'maximum_submitted_input_tokens':max(x['input_tokens']for x in u['calls']),'agent_wall_s':s['agent_wall_s'],'task_state':state,'termination':reason,'standard_agent_exit_status':exit_status,'last_finish_reason':last['finish_reason'],'first_messages_and_tools_sha256':hashlib.sha256(encoded).hexdigest(),'model_patch_sha256':o['model_patch_sha256'],'source_tree_sha256':o['source_tree_sha256'],'required_tests':g['required_tests'],'required_tests_passed':int(matched.group(1))if matched else None,'collected_tests':g['collected_tests'],'compilation_diagnostics':g.get('compilation_diagnostics',[]),'collection_failure':g.get('collection_failure'),'official_resource_probe':o['actual_resources']['actual'],'raw_case':f'capability/{arm}/task{i+1:03d}'};rows.append(row)
assert len(rows)==9 and len({x['task_id']for x in rows})==3
paired=[{'index':i,'source025_initial_inputs_and_tools_equal':rows[i]['first_messages_and_tools_sha256']==rows[i+3]['first_messages_and_tools_sha256']}for i in range(3)];assert all(x['source025_initial_inputs_and_tools_equal']for x in paired)
totals=[]
for cohort,_ in cohorts:
 z=[x for x in rows if x['cohort']==cohort];totals.append({'cohort':cohort,'unique_tasks':3,'successes':sum(x['success']for x in z),'actual_api_tokens':sum(x['actual_api_tokens']for x in z),'actual_api_calls':sum(x['actual_api_calls']for x in z)})
final=json.loads((a.final/'FINAL_RESULTS.json').read_text());assert sum(x['actual_api_tokens']for x in rows)==final['valid_task_tokens']
out={'scope':'Three preregistered tasks, one seed, nine admitted cases; two infrastructure-invalid attempts retained separately','cohorts':totals,'paired_initial_inputs':paired,'cases':rows,'valid_task_tokens':final['valid_task_tokens'],'invalid_infrastructure_tokens':final['invalid_infrastructure_tokens'],'invalid_infrastructure_calls':final['invalid_infrastructure_calls'],'control_tokens':final['control_tokens'],'actual_api_tokens_all':final['actual_api_tokens_all'],'actual_api_calls_all':final['actual_api_calls_all'],'provider_counter_reconciliation':final['epochs'],'GPU_hours_management_upper_bound':final['GPU_hours_upper_bound'],'GPU_management_windows':final['GPU_management_windows'],'all_reservations_restored':final['all_reservations_restored'],'additional_service358_activated':False}
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(out,ensure_ascii=False,indent=2))
fields=['cohort','index','task_id','success','actual_api_tokens','input_tokens','output_tokens','actual_api_calls','agent_wall_s','task_state','standard_agent_exit_status','required_tests_passed','required_tests','accepted_reservation_tokens_sum','reservation_denied_count','context_window','maximum_submitted_input_tokens','official_protocol_valid','model_patch_sha256']
with a.output.with_suffix('.csv').open('w',newline='',encoding='utf-8')as f:
 writer=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(rows)
print(json.dumps({'cohorts':totals,'actual_api_tokens_all':out['actual_api_tokens_all'],'GPU_hours_upper_bound':out['GPU_hours_management_upper_bound']},ensure_ascii=False))
